export interface ClaimChainPart {
  trackId: string;
  fromFrame: number;
  toFrame: number;
}

export type ClaimChainUncertaintyKind = typeof ClaimChainUncertaintyKind[keyof typeof ClaimChainUncertaintyKind];


export const ClaimChainUncertaintyKind = {
  'track-end': 'track-end',
  swap: 'swap',
  continuity: 'continuity',
} as const;

/**
 * Where playback should stop and ask. Playback stops here and nowhere else: a track end is definitive, a swap is judged and only raised when the geometry or the tracker's own confidence passes a threshold.
 */
export interface ClaimChainUncertainty {
  kind: ClaimChainUncertaintyKind;
  frame: number;
  trackId: string;
  /** For a swap, the player the identity may have been exchanged with. */
  otherTrackId?: string;
  confidence: number;
  /** A plain sentence for the person watching. Never a code. */
  reason: string;
}

/**
 * The state of the identity map behind this recording. The chain only stops where a part has nothing to continue onto, so frequent stops mean the map is not joining this person's pieces -- which is either an empty map or one whose fingerprint no longer matches the bundle, in which case all of it is discarded silently.
 */
export type ClaimChainIdentityMap = {
  people: number;
  matchesBundle: boolean;
  tracks: number;
  segments: number;
  /**
     * Which linker produced this bundle, from the pipeline's own provenance stamp. Null means unstamped.
     * @nullable
     */
  linker: string | null;
};

export interface ClaimChain {
  /** Every question still open on this chain, earliest first (capped). The page stops at the next one AHEAD of the playhead and lists the ones behind it - a filled gap leaves questions behind, and a stop behind the playhead must be shown, never fired. */
  openQuestions: ClaimChainUncertainty[];
  /** Whether this claim counts as the person's match - enough of it claimed and nothing left to answer. The same rule that awards clips. */
  completed: boolean;
  /** The coverage this recording needs for a claim to count. */
  requiredCoveragePercent: number;
  /** True when this claimant has no chain but an administrator released their claim on the identity board - i.e. the claim was removed by someone else, not by the claimant. The page says so instead of looking like a fresh start. */
  resetByAdmin: boolean;
  recordingId: number;
  /** The caller's identity row on the identity board. The chain IS that identity, so a merge made in the video is a merge on the board. */
  identityId: string;
  /** The state of the identity map behind this recording. The chain only stops where a part has nothing to continue onto, so frequent stops mean the map is not joining this person's pieces -- which is either an empty map or one whose fingerprint no longer matches the bundle, in which case all of it is discarded silently. */
  identityMap: ClaimChainIdentityMap;
  /** @nullable */
  name: string | null;
  /** Send this back on writes; a mismatch is a 409, never a blind merge. */
  bundleFingerprint: string;
  frameRate: number;
  chain: ClaimChainPart[];
  coverageSeconds: number;
  coveragePercent: number;
  nextUncertainty: ClaimChainUncertainty | null;
  /**
     * Whether this decision's training label landed. A label write never fails the claim, so this is how a silently empty corpus becomes visible. Null on reads, which record nothing.
     * @nullable
     */
  labelRecorded: boolean | null;
}

export interface ClaimChainForUserInput {
  userId: number;
  /** @minItems 1 */
  parts: ClaimChainPart[];
  /** @nullable */
  name?: string | null;
  /** The bundle the parts were built against; a mismatch is a 409. */
  bundleFingerprint: string;
  dryRun?: boolean;
}

/**
 * The player's identity binding after the write; null on a dry run.
 */
export type ClaimChainForUserBinding = {
  personId: string;
  state: string;
} | null;

/**
 * The player's claim progress row after the write; null on a dry run.
 */
export type ClaimChainForUserProgress = {
  completed: boolean;
  claimedPercent: number;
  clipsUnlocked: number;
  stage: string;
} | null;

export type ClaimChainForUser = ClaimChain & {
  dryRun: boolean;
  userId: number;
  /** Dry run only. Why the chain would or would not count. */
  completionReason?: string;
  /** Dry run only. Scoreable events inside the claimed stretch. */
  earnedClipCount?: number;
  /** The player's identity binding after the write; null on a dry run. */
  binding: ClaimChainForUserBinding;
  /** The player's claim progress row after the write; null on a dry run. */
  progress: ClaimChainForUserProgress;
};

export interface ClaimChainConflict {
  error: string;
  currentBundleFingerprint?: string;
  conflict?: ClaimChainPart;
}

