export interface ClaimMatchResponse {
  /** A digest of manifest.identities as served. The identity board echoes it on save, and a save against a different value is refused - which is how a board opened before a player claimed themselves is stopped from overwriting that claim, independent of the vouched-fragment bindings. */
  identitiesFingerprint: string;
  recording: Recording;
  manifest: TrackingManifest;
  offPitchSpans: ClaimOffPitchSpan[];
  /** @minimum 0 */
  offPitchSeconds: number;
}

export interface ClaimMatchRosterPart {
  /** @minimum 0 */
  segmentIndex: number;
  segmentName: string;
  trackId: string;
  /**
     * Exact start frame from the referenced track in its stored bundle segment.
     * @minimum 0
     */
  fromFrame: number;
  /**
     * Exact end frame from the referenced track in its stored bundle segment.
     * @minimum 0
     */
  toFrame: number;
}

export interface ClaimMatchRosterPhoto {
  trackId: string;
  /** @minimum 0 */
  segmentIndex: number;
  /** @minimum 0 */
  frame: number;
  jpeg: string;
}

export interface ClaimMatchRosterPlayer {
  id: string;
  /** @nullable */
  name: string | null;
  /** @nullable */
  number: string | null;
  /** @minimum 0 */
  minutes: number;
  parts: ClaimMatchRosterPart[];
  photos: ClaimMatchRosterPhoto[];
}

export interface ClaimMatchRosterResponse {
  players: ClaimMatchRosterPlayer[];
}

export interface ClaimMatchClipGroup {
  recordingId: number;
  /** Human-readable match label. */
  recordingLabel: string;
  fieldName: string;
  date: string;
  clips: ClaimEarnedClip[];
}

export type ClaimMatchClipsResponse = ClaimMatchClipGroup[];

export type ClaimIdentityBindingResolutionMethod = typeof ClaimIdentityBindingResolutionMethod[keyof typeof ClaimIdentityBindingResolutionMethod];


export const ClaimIdentityBindingResolutionMethod = {
  'identity-map': 'identity-map',
  'track-fallback': 'track-fallback',
  chain: 'chain',
} as const;

export type ClaimIdentityBindingState = typeof ClaimIdentityBindingState[keyof typeof ClaimIdentityBindingState];


export const ClaimIdentityBindingState = {
  pending: 'pending',
  confirmed: 'confirmed',
  disputed: 'disputed',
  needs_resolution: 'needs_resolution',
  released: 'released',
  rejected: 'rejected',
} as const;

export interface ClaimVouchedFragment {
  trackId: string;
  /** @minimum 0 */
  fromFrame: number;
  /** @minimum 0 */
  toFrame: number;
}

export interface ClaimIdentityBinding {
  id: number;
  personId: string;
  trackingBundleId: number;
  bundleFingerprint: string;
  resolutionMethod: ClaimIdentityBindingResolutionMethod;
  /** @minimum 0 */
  supportCount: number;
  /** @minimum 0 */
  acceptedAnswerCount: number;
  /**
     * @minimum 0
     * @maximum 100
     */
  supportPercent: number;
  vouchedFragments: ClaimVouchedFragment[];
  state: ClaimIdentityBindingState;
  /** Claimant name. Returned only by the admin binding-list endpoint. */
  claimantName?: string;
  /** When the claimant created this binding. Returned only by the admin binding-list endpoint. */
  claimedAt?: string;
  /** @nullable */
  resolvedAt: string | null;
  updatedAt: string;
}

export type ClaimedMatchHistoryItemState = typeof ClaimedMatchHistoryItemState[keyof typeof ClaimedMatchHistoryItemState];


export const ClaimedMatchHistoryItemState = {
  pending: 'pending',
  confirmed: 'confirmed',
  disputed: 'disputed',
  needs_resolution: 'needs_resolution',
  released: 'released',
  rejected: 'rejected',
} as const;

export type ClaimedMatchHistoryItemResolutionMethod = typeof ClaimedMatchHistoryItemResolutionMethod[keyof typeof ClaimedMatchHistoryItemResolutionMethod];


export const ClaimedMatchHistoryItemResolutionMethod = {
  'identity-map': 'identity-map',
  'track-fallback': 'track-fallback',
  chain: 'chain',
} as const;

export interface ClaimedMatchHistoryItem {
  recordingId: number;
  recordingLabel: string;
  fieldName: string;
  date: string;
  state: ClaimedMatchHistoryItemState;
  personId: string;
  resolutionMethod: ClaimedMatchHistoryItemResolutionMethod;
  supportPercent: number;
  claimedAt: string;
}

export type ClaimedMatchHistoryResponse = ClaimedMatchHistoryItem[];

export interface ClaimMatchDispute {
  id: number;
  recordingId: number;
  recordingLabel: string;
  claimantUserId: number;
  claimantName: string;
  claimantEmail: string;
  personId: string;
  resolutionMethod: string;
  supportCount: number;
  acceptedAnswerCount: number;
  supportPercent: number;
  state: string;
  /** @nullable */
  currentOwnerUserId: number | null;
  /** @nullable */
  currentOwnerName: string | null;
  createdAt: string;
  updatedAt: string;
}

export type ClaimMatchDisputesResponse = ClaimMatchDispute[];

export interface ResolveClaimMatchDisputeInput {
  winnerUserId: number;
}

export interface AccountDeletionResponse {
  ok: boolean;
}

export type AccountDeletionErrorReason = typeof AccountDeletionErrorReason[keyof typeof AccountDeletionErrorReason];


export const AccountDeletionErrorReason = {
  upcoming_booking: 'upcoming_booking',
  admin: 'admin',
  field_owner: 'field_owner',
  rate_limited: 'rate_limited',
  clerk_failed: 'clerk_failed',
  data_failed: 'data_failed',
  not_found: 'not_found',
  unauthenticated: 'unauthenticated',
  forbidden: 'forbidden',
  invalid_id: 'invalid_id',
  self_delete: 'self_delete',
  last_admin: 'last_admin',
} as const;

export interface AccountDeletionError {
  error: string;
  reason: AccountDeletionErrorReason;
  activeFootageRequests?: number;
}

export type GetAdminAnalysisJobQuoteParams = {
/**
 * @exclusiveMinimum 0
 */
seconds: number;
};

export type ReplaceTrackingBundleBodyTwo = {
  /** ZIP file containing manifest.json and the segment JSON files */
  bundle: string;
};

